        "title": "2. Cấu trúc phủ định tuyệt đối: “一……也/都 + 不/没……”",
        "desc": "Dùng để nhấn mạnh sự phủ định hoàn toàn. Cấu trúc: 'Chủ ngữ + 一 + Lượng từ + Danh từ + 也/都 + 不/没 + Vị ngữ'. Khi danh từ không đếm được hoặc tính từ, dùng '一点儿 + 也/都 + 不/没'.",
