      "passage_zh": "今天下午，小刚和小丽去商场买衣服。小丽看到一条漂亮的裙子，才两百元，非常喜欢。小刚买了一件白衬衫和一条黑裤子。买完衣服，他们坐在咖啡馆里休息。桌子上放着两杯热咖啡和一块甜蛋糕，两个人一边喝咖啡一边聊天儿，觉得很舒服。",
