      "passage_zh": "春天来了，天气越来越暖和了。公园里的草绿了，花也开了，景色非常美丽。小丽很喜欢春天，但是她最近有点儿感冒发烧。为了照顾小丽，小刚每天都来给她做饭。在小刚的照顾下，小丽的病好得很快。为了感谢小刚，小丽打算周末请他吃大餐。",
