    "title_zh": "别忘了把空调关了。",
    "title_py": "Bié wàng le bǎ kōngtiáo guān le.",
    "title_vi": "Đừng quên tắt máy điều hòa nhé.",
    "dialogues": [
      {
        "title": "Đoạn 1: 下班离开办公室 (Tan làm rời khỏi văn phòng)",
        "location": "在办公室",
        "lines": [
          {
            "speaker": "同事A",
            "role": "male",
            "zh": "我要下班了，你还不走吗？",
            "py": "Wǒ yào xiàbān le, nǐ hái bù zǒu ma?",
            "vi": "Tôi chuẩn bị tan làm rồi, bạn vẫn chưa về à?"
          },
          {
            "speaker": "同事B",
            "role": "female",
            "zh": "我把这份电子邮件发完就走。",
            "py": "Wǒ bǎ zhè fèn diànzǐ yóujiàn fāwán jiù zǒu.",
            "vi": "Tôi gửi nốt bức thư điện tử này xong là về ngay."
          },
          {
            "speaker": "同事A",
            "role": "male",
            "zh": "走的时候别忘了把灯和空调关了。",
            "py": "Zǒu de shíhou bié wàng le bǎ dēng hé kōngtiáo guān le.",
            "vi": "Lúc về đừng quên tắt đèn và điều hòa nhé."
          },
          {
            "speaker": "同事B",
            "role": "female",
            "zh": "放心吧，我已经养成好习惯了，走前一定检查。",
            "py": "Fàngxīn ba, wǒ yǐjīng yǎngchéng hǎo xíguàn le, zǒu qián yídìng jiǎnchá.",
            "vi": "Yên tâm đi, tôi đã hình thành thói quen tốt rồi, trước khi đi nhất định sẽ kiểm tra."
          }
        ]
      },
      {
        "title": "Đoạn 2: 在图书馆借书 (Mượn sách ở thư viện)",
        "location": "在图书馆",
        "lines": [
          {
            "speaker": "学生",
            "role": "male",
            "zh": "老师，我想借这两本关于历史的书。",
            "py": "Lǎoshī, wǒ xiǎng jiè zhè liǎng běn guānyú lìshǐ de shū.",
            "vi": "Thưa thầy, em muốn mượn hai cuốn sách về lịch sử này ạ."
          },
          {
            "speaker": "管理员",
            "role": "female",
            "zh": "好的，请把学生证给我一下。",
            "py": "Hǎo de, qǐng bǎ xuéshengzhèng gěi wǒ yíxià.",
            "vi": "Được rồi, em đưa thẻ học sinh cho cô một chút."
          },
          {
            "speaker": "学生",
            "role": "male",
            "zh": "给您。请问可以借多长时间？",
            "py": "Gěi nín. Qǐngwèn kěyǐ jiè duō cháng shíjiān?",
            "vi": "Dạ gửi cô. Xin hỏi em có thể mượn trong bao lâu ạ?"
          },
          {
            "speaker": "管理员",
            "role": "female",
            "zh": "一个月左右，记得按时把书还回来。",
            "py": "Yí ge yuè zuǒyòu, jìde ànshí bǎ shū huán huílái.",
            "vi": "Khoảng chừng một tháng, nhớ mang sách trả đúng hạn nhé."
          }
        ]
      },
      {
        "title": "Đoạn 3: 乘地铁 (Đi tàu điện ngầm)",
        "location": "在地铁站",
        "lines": [
          {
            "speaker": "小刚",
            "role": "male",
            "zh": "我们坐地铁去，还是打车去？",
            "py": "Wǒmen zuò dìtiě qù, háishì dǎchē qù?",
            "vi": "Chúng mình đi tàu điện ngầm hay là bắt taxi đi?"
          },
          {
            "speaker": "小丽",
            "role": "female",
            "zh": "现在是下班时间，路上肯定堵车，坐地铁快得多。",
            "py": "Xiànzài shì xiàbān shíjiān, lùshang kěndìng dǔchē, zuò dìtiě kuài de duō.",
            "vi": "Bây giờ là giờ tan tầm, trên đường chắc chắn kẹt xe, đi tàu điện ngầm nhanh hơn nhiều."
          },
          {
            "speaker": "小刚",
            "role": "male",
            "zh": "坐地铁大概需要多长时间？",
            "py": "Zuò dìtiě dàgài xūyào duō cháng shíjiān?",
            "vi": "Đi tàu điện ngầm khoảng mất bao lâu?"
          },
          {
            "speaker": "小丽",
            "role": "female",
            "zh": "二十分钟左右就到了，快把地铁卡拿出来吧。",
            "py": "Èrshí fēnzhōng zuǒyòu jiù dào le, kuài bǎ dìtiěkǎ ná chūlái ba.",
            "vi": "Khoảng 20 phút là tới nơi rồi, mau lấy thẻ tàu điện ra đi anh."
          }
        ]
      },
      {
        "title": "Đoạn 4: 在饭馆吃饭 (Ăn cơm trong quán)",
        "location": "在饭馆",
        "lines": [
          {
            "speaker": "小刚",
            "role": "male",
            "zh": "服务员，请给我们拿一双筷子和两个杯子。",
            "py": "Fúwùyuán, qǐng gěi wǒmen ná yì shuāng kuàizi hé liǎng ge bēizi.",
            "vi": "Phục vụ ơi, lấy giúp chúng tôi một đôi đũa và hai chiếc cốc."
          },
          {
            "speaker": "服务员",
            "role": "female",
            "zh": "好的，两位还要点些什么饮料吗？",
            "py": "Hǎo de, liǎng wèi hái yào diǎn xiē shénme yǐnliào ma?",
            "vi": "Dạ được, hai vị có muốn gọi thêm đồ uống gì không ạ?"
          },
          {
            "speaker": "小刚",
            "role": "male",
            "zh": "再来一瓶啤酒吧，要冰的。",
            "py": "Zài lái yì píng píjiǔ ba, yào bīng de.",
            "vi": "Cho thêm một chai bia nữa nhé, lấy bia ướp lạnh."
          },
          {
            "speaker": "小丽",
            "role": "female",
            "zh": "你开车来的，千万别把酒喝了！",
            "py": "Nǐ kāichē lái de, qiānwàn bié bǎ jiǔ hē le!",
            "vi": "Anh lái xe đến đấy, tuyệt đối không được uống rượu bia đâu đấy!"
          }
        ]
      }
    ],
