      "passage_zh": "今天下午放学的时候，天空中突然下起了大雨。小刚没有带伞，公共汽车站也挤满了人。等了半天没有坐上车，小刚就决定一个人走回家。虽然路上鞋子和裤子都淋湿了，但是他觉得走在雨中空气特别清新，很舒服。回到家，妈妈看到他满身是水，心疼地问：“你怎么不坐车呢？”小刚笑着说：“今天等车的人太多了，我是走回来的，顺便锻炼锻炼身体！”",
